package scorer
import("bytes";"crypto/sha256";"encoding/hex";"encoding/json";"fmt";"io";"os";"path/filepath";"reflect";"sort";"github.com/LuigiD5555/origami/internal/lab/artifact";"github.com/LuigiD5555/origami/internal/lab/observation")
const ExpectationSchemaV1="ohf.expectation.v1";const ScoreSchemaV1="ohf.score.v1"
type Expectation struct{Schema string `json:"schema"`;ID string `json:"id"`;RequiredStatus observation.Status `json:"required_status"`;Fields map[string]any `json:"fields"`};type Mismatch struct{Field string `json:"field"`;Expected any `json:"expected"`;Observed any `json:"observed"`};type Score struct{Schema string `json:"schema"`;ScoreID string `json:"score_id"`;RunID string `json:"run_id"`;ObservationID string `json:"observation_id"`;ExpectationID string `json:"expectation_id"`;Verdict string `json:"verdict"`;FailureKind string `json:"failure_kind,omitempty"`;Matched int `json:"matched"`;Total int `json:"total"`;Mismatches []Mismatch `json:"mismatches,omitempty"`}
func LoadExpectation(path string)(Expectation,error){b,err:=os.ReadFile(path);if err!=nil{return Expectation{},err};dec:=json.NewDecoder(bytes.NewReader(b));dec.DisallowUnknownFields();dec.UseNumber();var e Expectation;if err:=dec.Decode(&e);err!=nil{return e,err};var x any;if err:=dec.Decode(&x);err!=io.EOF{return e,fmt.Errorf("expectation trailing JSON")};if e.Schema!=ExpectationSchemaV1||e.ID==""||e.Fields==nil{return e,fmt.Errorf("invalid expectation")};if e.RequiredStatus==""{e.RequiredStatus=observation.Known};return e,nil}
func Evaluate(runID,observationID string,o observation.Envelope,e Expectation)Score{s:=Score{Schema:ScoreSchemaV1,RunID:runID,ObservationID:observationID,ExpectationID:e.ID,Total:len(e.Fields),Mismatches:[]Mismatch{}};if o.Status!=e.RequiredStatus{s.Verdict="FAIL";s.FailureKind="EPISTEMIC_"+string(o.Status);s.ScoreID=scoreID(s);return s};keys:=make([]string,0,len(e.Fields));for k:=range e.Fields{keys=append(keys,k)};sort.Strings(keys);for _,k:=range keys{exp:=normalize(e.Fields[k]);obs,ok:=o.Observations[k];if !ok||!reflect.DeepEqual(exp,normalize(obs)){s.Mismatches=append(s.Mismatches,Mismatch{Field:k,Expected:exp,Observed:normalize(obs)})}else{s.Matched++}};if len(s.Mismatches)==0{s.Verdict="PASS"}else{s.Verdict="FAIL";s.FailureKind="WRONG_OBSERVATION"};s.ScoreID=scoreID(s);return s}
func Write(root,runID string,s Score)(string,error){b,err:=json.MarshalIndent(s,"","  ");if err!=nil{return "",err};p:=filepath.Join(root,"runs",runID,"scores",s.ScoreID+".json");if err:=artifact.WriteExact(p,append(b,'\n'));err!=nil{return "",err};_,err=artifact.Write(filepath.Join(root,"runs",runID));return p,err};func scoreID(s Score)string{clone:=s;clone.ScoreID="";b,_:=json.Marshal(clone);h:=sha256.Sum256(b);return hex.EncodeToString(h[:])[:16]};func normalize(v any)any{if n,ok:=v.(json.Number);ok{return n.String()};return v}
